// TypeScript Version: 4.1

/// <reference types="@stdlib/types"/>

import { Complex128Array } from '@stdlib/types/array';
import { Layout, TransposeOperation } from '@stdlib/types/blas';

/**
* Interface describing `zgemv`.
*/
interface Routine {
	/**
	* Performs one of the matrix-vector operations `y = α*A*x + β*y`, or `y = α*A^T*x + β*y`, or `y = α*A^H*x + β*y`, where `α` and `β` are scalars, `X` and `Y` are vectors and `A` is an `M` by `N` matrix.
	*
	* @param order - storage layout
	* @param trans - specifies whether `A` should be transposed, conjugate-transposed, or not transposed
    * @param M - number of rows in the matrix `A`
	* @param N - number of columns in the matrix `A`
	* @param alpha - scalar constant
	* @param A - input matrix
	* @param LDA - stride of the first dimension of `A` (a.k.a., leading dimension of the matrix `A`)
	* @param x - first input vector
	* @param strideX - stride length for `x`
	* @param beta - scalar constant
	* @param y - second input vector
	* @param strideY - stride length for `y`
	* @returns `y`
	*
	* @example
	* var Complex128Array = require( '@stdlib/array/complex128' );
	* var Complex128 = require( '@stdlib/complex/float64/ctor' );
	*
	* var x = new Complex128Array( [ 1.0, 2.0, 3.0, 4.0 ] );
	* var y = new Complex128Array( [ 0.0, 0.0, 0.0, 0.0 ] );
	* var A = new Complex128Array( [ 1.0, 1.0, 2.0, 2.0, 3.0, 3.0, 4.0, 4.0 ] );
	* var alpha = new Complex128( 1.0, 0.0 );
	* var beta = new Complex128( 0.0, 0.0 );
	*
	* zgemv( 'row-major', 'no-transpose', 2, 2, alpha, A, 2, x, 1, beta, y, 1 );
	* // A => <Complex128Array>[ -3.0, 17.0, -7.0, 37.0 ]
	*/
	( order: Layout, trans: TransposeOperation, M: number, N: number, alpha: number, A: Complex128Array, LDA: number, x: Complex128Array, strideX: number, beta: number, y: Complex128Array, strideY: number ): Complex128Array;

	/**
	* Performs one of the matrix-vector operations `y = α*A*x + β*y`, or `y = α*A^T*x + β*y`, or `y = α*A^H*x + β*y`, using alternative semantics indexing and where `α` and `β` are scalars, `X` and `Y` are vectors and `A` is an `M` by `N` matrix.
	*
	* @param trans - specifies whether `A` should be transposed, conjugate-transposed, or not transposed
	* @param M - number of rows in the matrix `A`
	* @param N - number of columns in the matrix `A`
	* @param alpha - scalar constant
	* @param A - input matrix
	* @param strideA1 - stride of the first dimension of `A`
	* @param strideA2 - stride of the second dimension of `A`
	* @param offsetA - starting index for `A`
	* @param x - first input vector
	* @param strideX - `x` stride length
	* @param offsetX - starting index for `x`
	* @param beta - scalar constant
	* @param y - second input vector
	* @param strideY - `y` stride length
	* @param offsetY - starting index for `y`
	* @returns `y`
	*
	* @example
	* var Complex128Array = require( '@stdlib/array/complex128' );
	* var Complex128 = require( '@stdlib/complex/float64/ctor' );
	*
	* var x = new Complex128Array( [ 1.0, 2.0, 3.0, 4.0 ] );
	* var y = new Complex128Array( [ 0.0, 0.0, 0.0, 0.0 ] );
	* var A = new Complex128Array( [ 1.0, 1.0, 2.0, 2.0, 3.0, 3.0, 4.0, 4.0 ] );
	* var alpha = new Complex128( 1.0, 0.0 );
	* var beta = new Complex128( 0.0, 0.0 );
	*
	* zgemv.ndarray( 'row-major', 'no-transpose', 2, 2, alpha, A, 2, 1, 0, x, 1, 0, beta, y, 1, 0 );
	* // A => <Complex128Array>[ -3.0, 17.0, -7.0, 37.0 ]
	*/
	ndarray( trans: TransposeOperation, M: number, N: number, alpha: number, A: Complex128Array, strideA1: number, strideA2: number, offsetA: number, x: Complex128Array, strideX: number, offsetX: number, beta: number, y: Complex128Array, strideY: number, offsetY: number ): Complex128Array;
}

/**
* Performs one of the matrix-vector operations `y = α*A*x + β*y`, or `y = α*A^T*x + β*y`, or `y = α*A^H*x + β*y`, where `α` and `β` are scalars, `X` and `Y` are vectors and `A` is an `M` by `N` matrix.
*
* @param order - storage layout
* @param trans - specifies whether `A` should be transposed, conjugate-transposed, or not transposed
* @param M - number of rows in the matrix `A`
* @param N - number of columns in the matrix `A`
* @param alpha - scalar constant
* @param A - input matrix
* @param LDA - stride of the first dimension of `A` (a.k.a., leading dimension of the matrix `A`)
* @param x - first input vector
* @param strideX - stride length for `x`
* @param beta - scalar constant
* @param y - second input vector
* @param strideY - stride length for `y`
* @returns `y`
*
* @example
* var Complex128Array = require( '@stdlib/array/complex128' );
* var Complex128 = require( '@stdlib/complex/float64/ctor' );
*
* var x = new Complex128Array( [ 1.0, 2.0, 3.0, 4.0 ] );
* var y = new Complex128Array( [ 0.0, 0.0, 0.0, 0.0 ] );
* var A = new Complex128Array( [ 1.0, 1.0, 2.0, 2.0, 3.0, 3.0, 4.0, 4.0 ] );
* var alpha = new Complex128( 1.0, 0.0 );
* var beta = new Complex128( 0.0, 0.0 );
*
* zgemv( 'row-major', 'no-transpose', 2, 2, alpha, A, 2, x, 1, beta, y, 1 );
* // A => <Complex128Array>[ -3.0, 17.0, -7.0, 37.0 ]
*
* @example
* var Complex128Array = require( '@stdlib/array/complex128' );
* var Complex128 = require( '@stdlib/complex/float64/ctor' );
*
* var x = new Complex128Array( [ 1.0, 2.0, 3.0, 4.0 ] );
* var y = new Complex128Array( [ 0.0, 0.0, 0.0, 0.0 ] );
* var A = new Complex128Array( [ 1.0, 1.0, 2.0, 2.0, 3.0, 3.0, 4.0, 4.0 ] );
* var alpha = new Complex128( 1.0, 0.0 );
* var beta = new Complex128( 0.0, 0.0 );
*
* zgemv.ndarray( 'row-major', 'no-transpose', 2, 2, alpha, A, 2, 1, 0, x, 1, 0, beta, y, 1, 0 );
* // A => <Complex128Array>[ -3.0, 17.0, -7.0, 37.0 ]
*/
declare var zgemv: Routine;


// EXPORTS //

export = zgemv;
